create or replace function public.publish_fleet_route_notification(p_route_id uuid,p_event_type text,p_title text,p_body text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_route public.fleet_routes%rowtype; v_event uuid; v_allowed boolean; begin select * into v_route from public.fleet_routes where id=p_route_id; if not found then raise exception 'fleet route not found'; end if; select coalesce((select is_admin from public.profiles where id=auth.uid()),false) or exists(select 1 from public.app_business_memberships m where m.business_id=v_route.business_id and m.user_id=auth.uid()) or exists(select 1 from public.fleet_drivers d where d.id=v_route.driver_id and lower(coalesce(d.email,''))=lower(coalesce((select email from auth.users where id=auth.uid()),''))) into v_allowed; if not v_allowed then raise exception 'not authorized for fleet route'; end if; insert into public.fleet_route_updates(route_id,update_type,actor_user_id,payload) values(p_route_id,p_event_type,auth.uid(),coalesce(p_payload,'{}'::jsonb)); select public.publish_intelligence_location_event(null,p_event_type,p_title,p_body,jsonb_build_object('fleet_route_id',p_route_id,'business_id',v_route.business_id)||coalesce(p_payload,'{}'::jsonb),0,'fleet:'||p_route_id::text||':'||p_event_type||':'||date_trunc('minute',now())::text) into v_event; return v_event; end; $$;
